  '.cxb-hl-string { color: #188038; }',                       // string values: green
  '.cxb-hl-number { color: #e36209; }',                       // numbers: orange
  '.cxb-hl-literal { color: #cf222e; font-weight: 600; }',    // true/false/null: red
